@use '../abstracts' as *;

.c-home { overflow: hidden; color: $black; }
.c-home h1, .c-home h2, .c-home h3, .c-home p { margin: 0; }
.c-home h2 { font-size: 5.2rem; line-height: 1.05; font-weight: 700; }
.c-home-button { display: inline-flex; align-items: center; justify-content: center; gap: 2.2rem; border: 0; border-radius: 5rem; padding: 1.5rem 2.8rem; background: $rudnik-green; color: $white; font-weight: 700; font-size: 1.6rem; text-decoration: none; white-space: nowrap; }
.c-home-button--outline { background: transparent; border: 1px solid $white; }
.c-home-hero { width: min(1840px, calc(100% - 80px)); height: 800px; margin: 0 auto 112px; background-position: center; background-size: cover; border-radius: 2.6rem; position: relative; color: $white; }
.c-home-hero__content { position: absolute; top: 190px; left: clamp(6rem, 8vw, 11.5rem); max-width: 620px; }
.c-home-hero h1 { font-size: 6rem; line-height: 1.1; margin-bottom: 6rem; }
.c-home-benefits { display: grid; min-height: 175px; grid-template-columns: repeat(5, 1fr); align-items: start; text-align: center; margin-bottom: 102px; }
.c-home-benefit img { display: block; width: 60px; height: 60px; object-fit: contain; margin: 0 auto 1.8rem; }
.c-home-benefit p { font-size: 2.5rem; line-height: 1.2; font-weight: 500; }
.c-home-crops { background: $rudnik-light; padding: 8.5rem 0 28.3rem; }
.c-home-crops h2 { font-size: 5.6rem; }.c-home-kicker { margin: 1rem 0 5rem; color: $rudnik-green; font-weight: 700; font-size: 2rem; }
.c-home-crop-group { margin-top: 3rem; }.c-home-crop-group h3 { display: inline-block; min-width: 155px; margin-bottom: 2rem; padding: .7rem 3rem; border-radius: 1.5rem; background: var(--crop-colour); color: $white; text-align: center; font-size: 2rem; }
